create table public.admin_rate_limits(bucket_key text not null check(bucket_key~'^[0-9a-f]{64}$'),operation text not null,window_start timestamptz not null,count integer not null check(count>0),expires_at timestamptz not null,updated_at timestamptz not null default now(),primary key(bucket_key,operation,window_start));
alter table public.admin_rate_limits enable row level security;alter table public.admin_rate_limits force row level security;alter table public.admin_rate_limits owner to postgres;
revoke all on table public.admin_rate_limits from public,anon,authenticated,persi_worker,persi_readonly;grant select,insert,update,delete on table public.admin_rate_limits to persi_app;create policy admin_rate_limits_server_all on public.admin_rate_limits for all to persi_app using(true) with check(true);
create function public.consume_admin_rate_limit(p_key text,p_operation text,p_limit integer,p_window_seconds integer) returns table(allowed boolean,retry_after integer,current_count integer) language plpgsql security definer set search_path=pg_catalog,public as $$declare v_start timestamptz;begin if p_key!~'^[0-9a-f]{64}$' or p_operation not in('admin.login','admin.mfa.enroll','admin.mfa.verify','admin.mutation','admin.security') or p_limit<1 or p_window_seconds<1 then raise exception using errcode='22023',message='INVALID_RATE_LIMIT_INPUT';end if;v_start=to_timestamp(floor(extract(epoch from clock_timestamp())/p_window_seconds)*p_window_seconds);return query with consumed as(insert into public.admin_rate_limits values(p_key,p_operation,v_start,1,v_start+make_interval(secs=>p_window_seconds),clock_timestamp()) on conflict(bucket_key,operation,window_start) do update set count=admin_rate_limits.count+1,updated_at=clock_timestamp() returning count) select consumed.count<=p_limit,greatest(0,ceil(extract(epoch from(v_start+make_interval(secs=>p_window_seconds)-clock_timestamp())))::integer),consumed.count from consumed;delete from public.admin_rate_limits where expires_at<clock_timestamp()-interval '1 hour';end$$;
alter function public.consume_admin_rate_limit(text,text,integer,integer) owner to postgres;revoke all on function public.consume_admin_rate_limit(text,text,integer,integer) from public,anon,authenticated;grant execute on function public.consume_admin_rate_limit(text,text,integer,integer) to persi_app;
